insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('2f455432-90cf-5c47-ae0b-086127f6b07e', 'drill-math-psda', 'Math: Problem-Solving and Data', 'Ratios, percentages, statistics, probability', 'drill', 'math', 'psda', 'mixed', 'Rates and proportions, percentage change, one- and two-variable data, probability, sampling and statistical claims.', 22) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('3684ae65-e350-57ce-ad6e-4a95c4731e55', '2f455432-90cf-5c47-ae0b-086127f6b07e', 1, 'Math: Problem-Solving and Data', 'math', 800) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0e2156ad-1fc1-5970-a86b-da688a9fb03a', '3684ae65-e350-57ce-ad6e-4a95c4731e55', 1, 'psda', 'percentages', 'easy', 'mc', null, 'What is 35 percent of 240?', '[{"key":"A","text":"70"},{"key":"B","text":"84"},{"key":"C","text":"96"},{"key":"D","text":"104"}]'::jsonb, 'B', null, 'Multiplying gives 0.35 × 240 = 84. Choice A is 35 percent of 200, which comes from rounding the base rather than computing it exactly.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d927516e-762c-5838-a390-80fd72b87d04', '3684ae65-e350-57ce-ad6e-4a95c4731e55', 2, 'psda', 'ratios_rates_proportions', 'easy', 'spr', null, 'A printer produces 18 pages per minute. How many minutes does it take to print 486 pages?', null, '27', '["27.0"]'::jsonb, 'Dividing gives 486 ÷ 18 = 27 minutes. Multiplying instead of dividing would give an implausible 8,748, a useful check that the operation was chosen correctly.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0d2fd230-eac2-5c48-a0e7-736e72f29157', '3684ae65-e350-57ce-ad6e-4a95c4731e55', 3, 'psda', 'one_var_data', 'medium', 'mc', null, 'The mean of five test scores is 82. Four of the scores are 78, 85, 90, and 76. What is the fifth score?', '[{"key":"A","text":"79"},{"key":"B","text":"81"},{"key":"C","text":"82"},{"key":"D","text":"84"}]'::jsonb, 'B', null, 'The total must be 5 × 82 = 410, and the four known scores sum to 329, so the fifth is 81. Choice C assumes the missing value equals the mean, which is only true when the other scores balance exactly.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('3672b24e-6ec0-5787-a07b-b2ba1f8bbd80', '3684ae65-e350-57ce-ad6e-4a95c4731e55', 4, 'psda', 'two_var_data', 'medium', 'mc', null, 'A scatterplot of study hours and exam scores for 40 students shows a line of best fit with slope 4.2 and intercept 51. What does the slope indicate?', '[{"key":"A","text":"A student who does not study is predicted to score 4.2."},{"key":"B","text":"Each additional hour of study is associated with a predicted increase of about 4.2 points."},{"key":"C","text":"The average exam score is 4.2 points."},{"key":"D","text":"Studying causes scores to rise by exactly 4.2 points."}]'::jsonb, 'B', null, 'The slope of a line of best fit gives the predicted change in the response for a one-unit change in the predictor. Choice D overreaches by claiming causation from an observational scatterplot, and choice A describes the intercept.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8d8d5a9b-b1dd-53cd-a53a-c19cd739c59c', '3684ae65-e350-57ce-ad6e-4a95c4731e55', 5, 'psda', 'probability', 'medium', 'spr', null, 'A survey of 200 commuters found that 130 take the bus and 45 of those bus riders also cycle. If one bus rider is chosen at random, what is the probability that the person also cycles? Give your answer as a decimal rounded to the nearest hundredth.', null, '0.35', '[".35","9/26","0.346"]'::jsonb, 'The relevant denominator is the 130 bus riders, not all 200 commuters, so the probability is 45/130 ≈ 0.35. Using 200 as the denominator gives 0.225, which answers a different question.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('bc960570-3dd0-5a7c-a680-9dc2da809c31', '3684ae65-e350-57ce-ad6e-4a95c4731e55', 6, 'psda', 'percentages', 'hard', 'mc', null, 'A population grows by 10 percent one year and then falls by 10 percent the next. Compared with the start, the population after two years is', '[{"key":"A","text":"unchanged."},{"key":"B","text":"1 percent lower."},{"key":"C","text":"1 percent higher."},{"key":"D","text":"10 percent lower."}]'::jsonb, 'B', null, 'Multiplying by 1.1 and then 0.9 gives 0.99, so the population is 1 percent below its starting value. Choice A assumes the percentages cancel, but the second one is taken from a larger base.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('be93ee96-628c-5595-a27a-d39f9e8a84e8', '3684ae65-e350-57ce-ad6e-4a95c4731e55', 7, 'psda', 'evaluating_claims', 'hard', 'mc', null, 'A company emails a satisfaction survey to all customers and reports that 88 percent of respondents are satisfied. Which is the strongest objection to generalising this figure to all customers?', '[{"key":"A","text":"The sample is too small to be meaningful."},{"key":"B","text":"Customers who respond voluntarily may differ systematically from those who do not."},{"key":"C","text":"Satisfaction cannot be measured numerically."},{"key":"D","text":"The survey should have been conducted by telephone."}]'::jsonb, 'B', null, 'Voluntary response produces self-selection bias, which is a problem of who answers rather than of how many. Choice A misses the point because even a very large voluntary sample stays biased.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7352a063-8f20-56ab-ae3e-a5d8470fa7a0', '3684ae65-e350-57ce-ad6e-4a95c4731e55', 8, 'psda', 'sample_stats_moe', 'hard', 'mc', null, 'Two polls estimate the same quantity. Poll A surveys 400 people and Poll B surveys 1,600, both by simple random sampling. Compared with Poll A, Poll B''s margin of error is approximately', '[{"key":"A","text":"four times as large."},{"key":"B","text":"twice as large."},{"key":"C","text":"half as large."},{"key":"D","text":"one quarter as large."}]'::jsonb, 'C', null, 'Margin of error scales with 1/√n, so quadrupling the sample size halves it. Choice D assumes a direct inverse relationship with n rather than with its square root.') on conflict (id) do nothing;
